Translate("deDE", "orgrimmar", {
	title = "Orgrimmar",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Orgrimmar ist die {link:capital-city}Hauptstadt{/link} der {link:horde}Horde{/link}, eine Festungsstadt in den Bergen des nördlichen {link:durotar}Durotar{/link}. Ihre Mauern sind aus Holz, Stein und Eisen, und vieles von ihr ist in den roten Fels der Schluchten gehauen. Durch ihr großes Tor ziehen Krieger der {link:orcs}Orcs{/link}, Jäger der {link:trolls}Trolle{/link}, Älteste der {link:tauren}Tauren{/link} und die bleichen Gesandten der {link:forsaken}Verlassenen{/link}. In ihrem Herzen liegt die Halle des Kriegshäuptlings. Die Stadt trägt den Namen von {link:orgrim-doomhammer}Orgrim Doomhammer{/link}, der starb, damit sein Volk frei sein konnte, und sie soll der Welt zeigen, was aus den Orcs geworden ist: keine Kriegsmaschine von Dämonen, sondern eine Nation.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Als der Krieg gegen die {link:burning-legion}Brennende Legion{/link} gewonnen war, brachte {link:thrall}Thrall{/link} sein Volk an die Ostküste von {link:kalimdor}Kalimdor{/link} und machte sich daran, ihm eine Heimat zu bauen. Er wählte einen Ort, an dem die nördlichen Berge der Stadt den Rücken decken würden, und benannte ihn nach Doomhammer, seinem Freund und Lehrer. Die {link:orcs}Orcs{/link} errichteten sie nicht allein. Die {link:tauren}Tauren{/link}, die {link:darkspear-trolls}Darkspear{/link} und die Goblins legten mit Hand an, und die Stadt wuchs rasch, Tal um Tal. Noch während sie gebaut wurde, kamen die {link:humans}Menschen{/link} von {link:kul-tiras}Kul Tiras{/link}, um sie niederzureißen. Sie scheiterten, und Orgrimmar blieb stehen.]=],
		},
		{
			title = "Die Gegenwart",
			text = [=[Orgrimmar ist die größte Stadt der {link:horde}Horde{/link} und ihr Herz. {link:thrall}Thrall{/link} herrscht von {link:grommash-hold}Grommash Hold{/link} aus, mit dem Häuptling der {link:darkspear-trolls}Darkspear{/link} und seinen alten Ratgebern an seiner Seite. Ihre Märkte sind laut, ihre Übungshallen voll, und ihre jungen Krieger dürsten nach ihrer ersten Schlacht. Doch die Stadt hat Feinde innerhalb ihrer Mauern. Die Kultisten der {link:burning-blade}Burning Blade{/link} flüstern im {link:cleft-of-shadow}Cleft of Shadow{/link}, und unter der Stadt, in den brennenden Höhlen des Ragefireabgrunds, sammelt eine Sekte des {link:shadow-council}Schattenrats{/link} ihre Kräfte. Thrall weiß mehr über sie, als sie glauben.]=],
		},
		{
			title = "Bewohner",
			text = [=[• {b}Die {link:orcs}Orcs{/link}.{/b} Krieger, Schamanen, Schmiede und Händler, frei vom Fluch des Dämons und stolz darauf.
• {b}Die Darkspeartrolle.{/b} Sie haben ihr eigenes Viertel im {link:valley-of-spirits}Valley of Spirits{/link}.
• {b}Die {link:tauren}Tauren{/link}.{/b} Älteste und Reisende aus {link:thunder-bluff}Thunder Bluff{/link}, Verbündete des Kriegshäuptlings.
• {b}Die Verlassenen.{/b} Gesandte von {link:sylvanas-windrunner}Sylvanas Windrunner{/link}, neu in die {link:horde}Horde{/link} aufgenommen und mit einigem Unbehagen beobachtet.
• {b}Die Goblins.{/b} Händler und Ingenieure, die jedem dienen, der zahlt.
• {b}Die Burning Blade.{/b} Verborgen unter allen anderen, wie die Fäulnis in einem gesunden Balken.]=],
		},
		{
			title = "Geschichte",
			text = [=[• {b}Die Gründung.{/b} Die Stadt wurde nach der {link:battle-of-mount-hyjal}Schlacht um den Berg Hyjal{/link} errichtet, während die {link:orcs}Orcs{/link} das Land ringsum zähmten und {link:quilboar}Stacheleber{/link}, {link:centaurs}Zentauren{/link} und {link:harpies}Harpyien{/link} vertrieben.
• {b}Der Krieg des Admirals.{/b} Die Flotte von {link:daelin-proudmoore}Daelin Proudmoore{/link} bedrohte die neue Stadt vom Meer aus. Die {link:horde}Horde{/link} zerschlug die Festung des Admirals und erschlug ihn in {link:theramore-isle}Theramore{/link}.
• {b}Die Gegenwart.{/b} Die Horde ist um die Verlassenen von {link:lordaeron}Lordaeron{/link} gewachsen, und Orgrimmar ist zum Treffpunkt all ihrer Völker geworden.]=],
		},
		{
			title = "Überlieferungen der Stadt",
			text = [=[• Die Festung des Kriegshäuptlings heißt {link:grommash-hold}Grommash Hold{/link}, nach {link:grom-hellscream}Grom Hellscream{/link}, der den Dämon {link:mannoroth}Mannoroth{/link} erschlug und die {link:orcs}Orcs{/link} vom Blutfluch befreite.
• Wenn ein Held der {link:horde}Horde{/link} den Kopf eines großen Feindes heimbringt, wird er im {link:valley-of-strength}Valley of Strength{/link} aufgerichtet, damit die ganze Stadt ihn sieht.
• In der Taverne im Valley of Strength trinkt ein Taure namens {link:gamon}Gamon{/link}. Er dient einem Troll, der mit den Piraten der Südküste handelt, und er ist selten nüchtern.
• Die Schurken der Stadt sagen, dass eine Gesellschaft namens Shattered Hand in den Schatten des Cleft wirkt und dass sie den Kriegshäuptling für zu vorsichtig hält.]=],
		},
	},
})

Translate("deDE", "valley-of-strength", {
	title = "Valley of Strength",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das Valley of Strength liegt gleich hinter dem großen Tor von {link:orgrimmar}Orgrimmar{/link}. Es ist der belebteste Ort der Stadt. Hier sind die Bank, das Auktionshaus und die Taverne, und darüber der Turm, auf dem die Windreiter landen. Grunzer bewachen jeden Weg. Reisende aus jedem Volk der {link:horde}Horde{/link} drängen sich auf seinen Pfaden, und Neuigkeiten aus ganz {link:kalimdor}Kalimdor{/link} gehen hier hindurch. Hier feiert die Horde auch ihre Siege. Die Köpfe gefallener Feinde werden über dem Tal aufgerichtet, und die Oberherren der Stadt rufen das Volk auf, die Helden zu ehren, die sie erbeutet haben.]=],
		},
	},
})

Translate("deDE", "the-drag", {
	title = "The Drag",
	aliases = { "Drag" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[The Drag ist eine lange, schattige Straße, die sich vom {link:valley-of-strength}Valley of Strength{/link} tiefer in die Stadt windet. Ihre Wände sind von Läden gesäumt. Lederverarbeiter, Schneider, Alchemisten und Ingenieure arbeiten in ihren Ständen, und der Rauch von Kochfeuern zieht zwischen den Planen hindurch. Es ist ein voller und lauter Ort, und nicht jeder Händler darin ist ehrlich. Wer ein Handwerk sucht, kommt hierher, um es zu erlernen. Von The Drag führen Wege ins {link:valley-of-honor}Valley of Honor{/link} und hinab ins {link:cleft-of-shadow}Cleft of Shadow{/link}.]=],
		},
	},
})

Translate("deDE", "cleft-of-shadow", {
	title = "Cleft of Shadow",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das Cleft of Shadow ist eine dunkle Schlucht im Herzen von {link:orgrimmar}Orgrimmar{/link}, in die selten die Sonne reicht. Es ist das Viertel der Schurken, Hexenmeister und Giftmischer. Der Hexenmeister {link:neeru-fireblade}Neeru Fireblade{/link} hat hier sein Zelt, und hier versammelt sich die Shattered Hand im Geheimen. Am Grund der Schlucht führt ein Gang hinab in den {link:ragefire-chasm}Ragefireabgrund{/link}. Die ehrlichen Leute der Stadt meiden das Cleft, und jenen, die dort leben, ist es so recht. Viele Geheimnisse des Kriegshäuptlings werden hier gehütet, und auch einige seiner Feinde.]=],
		},
	},
})

Translate("deDE", "valley-of-honor", {
	title = "Valley of Honor",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das Valley of Honor liegt im Nordosten von {link:orgrimmar}Orgrimmar{/link} und gehört den Kriegern der {link:horde}Horde{/link}. In der Halle der Tapferen lehren alte Veteranen die Jungen den Umgang mit Axt und Schild. Jäger haben hier ihre Hütten, und die Essen der Schmiede der Stadt brennen Tag und Nacht. Das Tal ist erfüllt vom Klang der Hämmer und den Rufen derer, die sich im Übungskampf messen. Ein {link:orcs}Orc{/link}, der als Krieger bekannt sein will, kommt hierher, um es zu beweisen.]=],
		},
	},
})

Translate("deDE", "valley-of-spirits", {
	title = "Valley of Spirits",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das Valley of Spirits zieht sich den Südwesten von {link:orgrimmar}Orgrimmar{/link} entlang. Es ist das Viertel der {link:darkspear-trolls}Darkspear{/link}. Ihre Hütten stehen zwischen den Bauten der {link:orcs}Orcs{/link}, und ihre Hexendoktoren, Priester und Magier üben hier die alten Wege des Stammes aus. Junge Trollpriester werden in diesem Tal in den Kreis ihrer Ältesten aufgenommen. Sein stiller Teich spiegelt die roten Wände darüber. Von allen Tälern der Stadt ist es das ruhigste, und die {link:trolls}Trolle{/link} halten es so. Hier gedenken die Darkspear der Inseln, die sie verloren haben.]=],
		},
	},
})

Translate("deDE", "valley-of-wisdom", {
	title = "Valley of Wisdom",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das Valley of Wisdom liegt im Nordwesten von {link:orgrimmar}Orgrimmar{/link}, fern vom Lärm des Tores. Es ist der Sitz des Kriegshäuptlings. An seinem Ende erhebt sich {link:grommash-hold}Grommash Hold{/link}, und darum versammeln sich die Schamanen der {link:horde}Horde{/link}, die die Jungen lehren, mit den {link:elements}Elementen{/link} zu sprechen, wie es ihre Ahnen auf Draenor taten. Die Ältesten der Stadt kommen hierher, um Rat zu geben und Rat zu empfangen. Es ist ein Ort des Lernens und der Macht. Viele, die die Gunst des Kriegshäuptlings suchen, gehen seinen Weg.]=],
		},
	},
})

Translate("deDE", "grommash-hold", {
	title = "Grommash Hold",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Grommash Hold ist die Festung des Kriegshäuptlings, in die Klippen des {link:valley-of-wisdom}Valley of Wisdom{/link} gebaut. Sie ist nach {link:grom-hellscream}Grom Hellscream{/link} benannt, dessen Opfer die {link:orcs}Orcs{/link} vom Blut des Dämons befreite. Ihre Halle ist gewaltig und düster, von Feuer erhellt. An ihrem fernen Ende hält {link:thrall}Thrall{/link} von seinem Thron aus Hof. {link:vol-jin}Vol'jin{/link} von den {link:darkspear-trolls}Darkspear{/link} steht an seiner Seite, mit dem alten Krieger {link:eitrigg}Eitrigg{/link} und dem Scharfseher {link:zor-lonetree}Zor Lonetree{/link}. Die Elitewachen der Kor'kron hüten ihre Tore, und niemand tritt ohne ihre Erlaubnis vor den Kriegshäuptling.]=],
		},
	},
})

Translate("deDE", "thrall", {
	title = "Thrall",
	subtitle = "Kriegshäuptling der Horde",
	found = "Grommash Hold, im Valley of Wisdom",
	hint = [=[Ersucht um eine Audienz beim Kriegshäuptling in Grommash Hold.]=],
	allegiance = "Horde · Frostwolfklan",
	aliases = { "Kriegshäuptling Thrall" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Thrall ist der Kriegshäuptling der {link:horde}Horde{/link}. Er wurde als Sohn von Durotan geboren, dem Häuptling des Frostwolfklans, und wuchs als Sklave unter {link:humans}Menschen{/link} auf. Er zerbrach seine Ketten, befreite sein Volk aus den Internierungslagern und führte es zu den alten Wegen der Schamanen zurück. Er führte es über das Meer nach {link:kalimdor}Kalimdor{/link} und gab ihm eine Heimat. Selbst seine Feinde zollen ihm Ehre.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Thrall schuf aus der Asche der alten eine neue {link:horde}Horde{/link}. Unter ihm sind die {link:orcs}Orcs{/link} nicht länger die Diener von Dämonen, und die Horde ist nicht länger nur eine Horde von Orcs.]=],
		},
		{
			title = "Der Sklave",
			text = [=[Durotan und seine Gefährtin Draka wurden in der Wildnis ermordet, als ihr Sohn noch ein Säugling war. Ein menschlicher Offizier namens {link:aedelas-blackmoore}Aedelas Blackmoore{/link} fand das Kind und brachte es nach {link:durnholde-keep}Burg Durnholde{/link}. Er nannte es Thrall, ein Wort für einen Sklaven, und zog es auf, damit es in der Arena kämpfe und vielleicht eines Tages eine Armee für ihn anführe. Ein Menschenmädchen, {link:taretha-foxton}Taretha Foxton{/link}, erwies ihm Freundlichkeit, und mit ihrer Hilfe entkam er.]=],
		},
		{
			title = "Der Befreier",
			text = [=[In der Wildnis fand Thrall {link:grom-hellscream}Grom Hellscream{/link} und die letzten freien Klans. Bei den Frostwölfen im {link:alterac-mountains}Alteracgebirge{/link} lehrte ihn der alte Schamane {link:drek-thar}Drek'Thar{/link}, mit den {link:elements}Elementen{/link} zu sprechen. Dann begegnete er {link:orgrim-doomhammer}Orgrim Doomhammer{/link}, und gemeinsam griffen sie die {link:internment-camps}Internierungslager{/link} an. Doomhammer fiel in der Schlacht, und bevor er starb, gab er Thrall seinen Hammer, seine Rüstung und seinen Titel. Thrall befreite die {link:orcs}Orcs{/link} und brach die Macht Blackmoores in {link:durnholde-keep}Durnholde{/link}.]=],
		},
		{
			title = "Der Auszug",
			text = [=[Ein Prophet kam in Träumen zu Thrall und sagte ihm, er solle sein Volk nach Westen führen. Er tat es. Ein Sturm warf seine Flotte auf die Inseln der {link:darkspear-trolls}Darkspear{/link}, und er rettete die {link:trolls}Trolle{/link} vor ihren Feinden. In {link:kalimdor}Kalimdor{/link} gewann er die Freundschaft von {link:cairne-bloodhoof}Cairne Bloodhoof{/link} und den {link:tauren}Tauren{/link}. Er sah Grom erneut dem Blut des Dämons verfallen, befreite ihn und sah ihn sterben, als er {link:mannoroth}Mannoroth{/link} erschlug. In der {link:battle-of-mount-hyjal}Schlacht um den Berg Hyjal{/link} kämpfte er an der Seite von {link:humans}Menschen{/link} und {link:night-elves}Nachtelfen{/link} gegen {link:archimonde}Archimonde{/link}. Danach gründete er {link:durotar}Durotar{/link} und {link:orgrimmar}Orgrimmar{/link}, und er schloss Frieden mit {link:jaina-proudmoore}Jaina Proudmoore{/link} von {link:theramore-isle}Theramore{/link}.]=],
		},
		{
			title = "Taten",
			text = [=[• Er befreite die {link:orcs}Orcs{/link} aus den Internierungslagern.
• Er führte die {link:horde}Horde{/link} nach {link:kalimdor}Kalimdor{/link} und gründete die Nation {link:durotar}Durotar{/link}.
• Er schmiedete Bündnisse mit den {link:darkspear-trolls}Darkspear{/link}, den {link:tauren}Tauren{/link} und den Verlassenen.]=],
		},
	},
	chapters = {
		{
			title = "Verborgene Feinde",
			hint = [=[Bringt dem Kriegshäuptling einen Beweis aus der Knochenhöhle.]=],
			text = [=[Thrall duldet keine Verräter, doch er schlägt nicht zu früh gegen sie zu. Ein zu früh geführter Schlag würde die Fäulnis nur tiefer treiben. Er brauchte jemanden, der jung und unbekannt war und dorthin gehen konnte, wohin seine eigenen Agenten nicht konnten. Das Abzeichen eines Leutnants der Burning Blade, aus der Knochenhöhle geholt, war der Schlüssel zur Tür des Feindes.]=],
		},
		{
			title = "Der Hexenmeister im Cleft",
			hint = "Bringt das Abzeichen zum Hexenmeister im Cleft of Shadow.",
			text = [=[Thrall enthüllte, was wenige in {link:orgrimmar}Orgrimmar{/link} wussten. Der Hexenmeister {link:neeru-fireblade}Neeru Fireblade{/link}, der behauptet, Dämonen zu jagen, ist der wahre Anführer der Burning Blade. Thrall weiß es seit Langem, und er lässt Neeru glauben, man vertraue ihm. Der Hexenmeister ist frei nützlicher als tot, denn durch ihn will Thrall den {link:shadow-council}Schattenrat{/link} finden und ihn endlich vernichten.]=],
		},
		{
			title = "Die Searing Blade",
			hint = [=[Streckt die Anführer der Searing Blade im Ragefireabgrund nieder.]=],
			text = [=[Unter der Stadt gehorchte eine Sekte namens Searing Blade {link:neeru-fireblade}Neeru{/link}. Ihre wahren Herren waren ein {link:satyrs}Satyr{/link}, {link:bazzalan}Bazzalan{/link}, und ein Hexenmeister, {link:jergosh-the-invoker}Jergosh{/link}. Auf Thralls Befehl wurden beide erschlagen, und niemand konnte sagen, dass es sein Werk war. Neeru tobte, und in seinem Zorn erzählte er seinem falschen Leutnant von neuen Plänen im {link:ashenvale}Eschental{/link} und im {link:the-barrens}Brachland{/link}.]=],
		},
		{
			title = "Rend lebt",
			hint = [=[Erfahrt, was der Kriegshäuptling gegen die Blackrock unternehmen wollte.]=],
			text = [=[Es kam Kunde, dass Rend Blackhand, lange für tot gehalten, an der Blackrockspitze eine eigene {link:horde}Horde{/link} aufgestellt und sich Kriegshäuptling genannt habe. Thrall schlug mit der Faust auf seinen Thron. Er verlangte Rends Kopf, und als man ihn ihm brachte, ehrte er den, der ihn gebracht hatte.]=],
		},
	},
	mentions = {
		{ text = "Verborgene Feinde, das Abzeichen" },
		{ text = "Verborgene Feinde, der Hexenmeister" },
		{ text = "Verborgene Feinde, die Searing Blade" },
		{ text = "Verborgene Feinde, der letzte Bericht" },
		{ text = "Eitriggs Weisheit" },
		{ text = "Für die {link:horde}Horde{/link}!" },
		{ text = "Die königliche Rettung" },
		{ text = "Die Prinzessin gerettet?" },
		{ text = "Die Vermittlung des Friedens" },
		{ text = "Sieg für die {link:horde}Horde{/link}" },
		{ text = "Der Fürst der {link:blackrock-mountain}Blackrock{/link}" },
	},
	bonds = {
		{ id = "vol-jin", name = "Vol'jin", note = "sein Ratgeber und Verbündeter" },
		{ id = "eitrigg", name = "Eitrigg", note = "sein alter Ratgeber" },
		{ id = "neeru-fireblade", name = "Neeru Fireblade", note = "der Verräter, den er beobachtet" },
		{ id = "orgrim-doomhammer", name = "Orgrim Doomhammer", note = "sein Freund und Mentor" },
		{ id = "grom-hellscream", name = "Grom Hellscream", note = "sein Freund, gefallen" },
		{ id = "cairne-bloodhoof", name = "Cairne Bloodhoof", note = "sein Verbündeter" },
		{ id = "jaina-proudmoore", name = "Jaina Proudmoore", note = "seine Verbündete im Frieden" },
	},
})

Translate("deDE", "vol-jin", {
	title = "Vol'jin",
	subtitle = "Häuptling der Darkspear",
	found = "Grommash Hold, an der Seite des Kriegshäuptlings",
	hint = [=[Sprecht mit dem Troll, der in Grommash Hold an der Seite des Kriegshäuptlings steht.]=],
	allegiance = "Horde · Darkspear",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Vol'jin ist der Häuptling der {link:darkspear-trolls}Darkspear{/link} und ein Schattenjäger von großem Können. Er ist der Sohn von {link:sen-jin-village}Sen'jin{/link}, der sein Leben gab, damit der Stamm den {link:orcs}Orcs{/link} in eine neue Welt folgen konnte. Vol'jin hält den Eid seines Vaters. Er steht in {link:grommash-hold}Grommash Hold{/link} an Thralls Seite, berät den Kriegshäuptling und spricht für sein Volk, während die Darkspear in ihrem Dorf am Meer auf den Tag warten, an dem sie ihre Inseln zurückerobern können.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Durch Vol'jin sind die {link:trolls}Trolle{/link} zu einem wahren Volk der {link:horde}Horde{/link} geworden und nicht nur zu ihren Verbündeten. Er ist der Beweis, dass Thralls Horde ein Bund freier Völker ist.]=],
		},
		{
			title = "Der Eid von Sen'jin",
			text = [=[Die {link:darkspear-trolls}Darkspear{/link} waren Ausgestoßene, aus den Dschungeln vertrieben und über die Inseln der südlichen Meere verstreut. Als ein Sturm Thralls Flotte an ihre Ufer warf, kämpfte der Stamm um sein Leben gegen {link:humans}Menschen{/link} und die {link:murlocs}Murlocs{/link} der Tiefe. {link:thrall}Thrall{/link} kämpfte an der Seite der {link:trolls}Trolle{/link}. Ihr Häuptling {link:sen-jin-village}Sen'jin{/link} wurde von den Murlocs verschleppt und kehrte nicht zurück, doch er hatte vorausgesehen, dass der Kriegshäuptling der {link:orcs}Orcs{/link} sein Volk in eine neue Heimat führen würde. Sen'jins Sohn schwor den Stamm auf die {link:horde}Horde{/link} ein.]=],
		},
		{
			title = "Die Inseln und der Verräter",
			text = [=[Nach dem Krieg gegen die Legion ließen sich die {link:darkspear-trolls}Darkspear{/link} auf den Echoinseln vor der Küste von {link:durotar}Durotar{/link} nieder. Ihr Frieden währte nicht lange. Die Flotte von {link:kul-tiras}Kul Tiras{/link} fiel über die Inseln her, und Vol'jin musste sein Volk in Sicherheit bringen, während die {link:horde}Horde{/link} gegen die Schiffe der {link:humans}Menschen{/link} zurückschlug. Dann kam ein schlimmerer Schlag: {link:zalazane}Zalazane{/link}, ein Hexendoktor ihres eigenen Stammes, wandte seine Magie gegen sie. Die freien Darkspear flohen aufs Festland und bauten dort ein Dorf, das sie nach {link:sen-jin-village}Sen'jin{/link} benannten.]=],
		},
		{
			title = "Taten",
			text = [=[• Er schwor die {link:darkspear-trolls}Darkspear{/link} nach dem Tod seines Vaters auf die {link:horde}Horde{/link} ein.
• Er führte sein Volk nach {link:kalimdor}Kalimdor{/link} und siedelte es auf den Echoinseln an.
• Er berät den Kriegshäuptling in {link:grommash-hold}Grommash Hold{/link}.
• Er warnt {link:thrall}Thrall{/link} immer wieder davor, den {link:humans}Menschen{/link} zu trauen.]=],
		},
		{
			title = "Nicht überliefert",
			text = [=[Wenig ist hier über Vol'jins Jugend geschrieben. Dieser Eintrag verzeichnet nur, was die Geschichtswerke und seine Taten offenbaren.]=],
		},
	},
	chapters = {
		{
			title = "Die Befehle des Admirals",
			hint = "Bringt die Befehle des toten Admirals nach Orgrimmar.",
			text = [=[Als die Befehle von {link:daelin-proudmoore}Daelin Proudmoore{/link} in {link:tiragarde-keep}Burg Tiragarde{/link} gefunden wurden, gelangten sie schließlich zu Vol'jin in {link:grommash-hold}Grommash Hold{/link}. Er las sie und war nicht überrascht. Lange hatte er den Kriegshäuptling gedrängt, den {link:humans}Menschen{/link} nicht zu trauen, und die Pläne des Admirals gaben ihm recht. Er frohlockte nicht. Er ging sofort, um {link:thrall}Thrall{/link} zu beraten.]=],
		},
		{
			title = "Der Hexmeister",
			hint = "Stürzt den Hexendoktor, der die Echoinseln beherrscht.",
			text = [=[Die Kunde von Zalazanes Fall erreichte {link:orgrimmar}Orgrimmar{/link} aus {link:sen-jin-village}Sen'jin{/link}. Für den Häuptling der {link:darkspear-trolls}Darkspear{/link} war es ein kleiner Trost. Der Fluch des Verräters liegt noch immer auf den Inseln, und viele von Vol'jins Volk irren dort noch mit leerem Geist umher. Der Tag der Heimkehr des Stammes ist noch nicht gekommen.]=],
		},
	},
	mentions = {
		{ text = "Die Befehle des Admirals" },
		{
			text = [=[{link:zalazane}Zalazane{/link}, erschlagen auf Bitten von {link:master-gadrin}Meister Gadrin{/link}]=],
		},
	},
	bonds = {
		{ id = "thrall", name = "Thrall", note = "sein Kriegshäuptling" },
		{ id = "zalazane", name = "Zalazane", note = "der Verräter seines Stammes" },
		{ id = "master-gadrin", name = "Meister Gadrin", note = "Ältester seines Volkes" },
		{ id = "eitrigg", name = "Eitrigg", note = "ein Mitratgeber" },
	},
})

Translate("deDE", "eitrigg", {
	title = "Eitrigg",
	subtitle = "Ratgeber des Kriegshäuptlings",
	found = "Grommash Hold",
	hint = [=[Sprecht mit dem alten Krieger, der den Kriegshäuptling in Grommash Hold berät.]=],
	allegiance = "Horde · Blackrockklan (ehemals)",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Eitrigg ist ein alter Orckrieger des Blackrockklans, der {link:thrall}Thrall{/link} als Ratgeber und als Aufseher über die Rekruten der {link:horde}Horde{/link} dient. Er kämpfte in den Kriegen der alten Horde unter Blackhand und Doomhammer. Er begann die Dämonenanbeter zu hassen, die sein Volk in die Irre führten, und eine Zeit lang verließ er die Horde ganz. Er kehrte zurück, als er von Thralls Vision einer Horde hörte, die von Schamanen statt von Dämonen geleitet wird.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Eitrigg ist eine Brücke zwischen der alten und der neuen {link:horde}Horde{/link}. Er kennt die Wege der {link:blackrock-mountain}Blackrock{/link} besser als jeder andere {link:orcs}Orc{/link} in {link:orgrimmar}Orgrimmar{/link}, und er weiß, was es kostet, sie zu verlassen.]=],
		},
		{
			title = "Taten",
			text = [=[• Er diente in den Tagen vor dem {link:dark-portal}Dunklen Portal{/link} als Leutnant des Kriegshäuptlings der {link:blackrock-mountain}Blackrock{/link}, an der Seite von {link:orgrim-doomhammer}Orgrim Doomhammer{/link}.
• Er bewachte im {link:second-war}Zweiten Krieg{/link} die Assassine {link:garona}Garona{/link}, und er ließ sie gehen, als sie floh.
• Er verließ die {link:horde}Horde{/link} und wanderte nach Norden in die Lande der {link:humans}Menschen{/link}, wo er gefangen genommen und vom Kriegshäuptling gerettet wurde.
• Er beaufsichtigt die Ausbildung neuer Rekruten für {link:thrall}Thrall{/link}.]=],
		},
	},
	chapters = {
		{
			title = "Rend lebt",
			hint = "Bringt Eitrigg Kunde von den Blackrock.",
			text = [=[Die Nachricht kam aus dem {link:badlands}Ödland{/link}: Rend Blackhand, Sohn des alten Kriegshäuptlings Blackhand, lebte und sammelte den Blackrockklan an der Blackrockspitze. Man hatte geglaubt, Rend sei vor langer Zeit erschlagen worden. Niemand in {link:orgrimmar}Orgrimmar{/link} kannte die {link:blackrock-mountain}Blackrock{/link} so wie Eitrigg, und niemand hatte einen größeren Anspruch auf Rache. Er gab die Nachricht an {link:thrall}Thrall{/link} weiter.]=],
		},
		{
			title = "Der Kopf von Rend",
			hint = "Bringt den Kopf von Rend Blackhand zum Kriegshäuptling.",
			text = [=[Als der Kopf von Rend vor den Kriegshäuptling gelegt wurde, sah Eitrigg den letzten Schatten des Klans gebrochen, dem er einst gedient hatte. Die {link:blackrock-mountain}Blackrock{/link} wurden erneut ins Chaos gestürzt. Für den alten Krieger war es eine beglichene Schuld.]=],
		},
	},
	mentions = {
		{ text = "Die neue {link:horde}Horde{/link}" },
		{ text = "Eitriggs Weisheit" },
		{ text = "Für die {link:horde}Horde{/link}!" },
	},
	bonds = {
		{ id = "thrall", name = "Thrall", note = "sein Kriegshäuptling und Retter" },
		{ id = "orgrim-doomhammer", name = "Orgrim Doomhammer", note = "sein alter Kampfgefährte" },
		{ id = "vol-jin", name = "Vol'jin", note = "ein Mitratgeber" },
		{ id = "tirion-fordring", name = "Tirion Fordring", note = "der Mensch, der ihn rettete" },
	},
})

Translate("deDE", "neeru-fireblade", {
	title = "Neeru Fireblade",
	subtitle = "Hexenmeister des Cleft of Shadow",
	found = "Sein Zelt im Cleft of Shadow",
	hint = [=[Sucht den Hexenmeister, dessen Zelt im Cleft of Shadow steht.]=],
	allegiance = "Horde (angeblich)",
	aliases = { "Neeru" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Neeru Fireblade ist ein Hexenmeister, der im {link:cleft-of-shadow}Cleft of Shadow{/link} lebt. Wenige {link:orcs}Orcs{/link} trauen seinesgleichen, denn es waren Hexenmeister, die die Orcs einst an die Dämonen banden. Neeru behauptet, seine Künste nur gegen die Dämonen einzusetzen. Seit dem letzten Krieg, sagt er, habe er jede Spur dämonischer Verderbnis in der Gesellschaft der Orcs aufgespürt, und er diene dem Kriegshäuptling dabei, die Kulte auszurotten, die sich in seiner Stadt verbergen.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Neeru steht im Mittelpunkt des Kampfes gegen die {link:burning-blade}Burning Blade{/link}. Jeder Faden des Kults in {link:durotar}Durotar{/link} scheint zurück ins {link:cleft-of-shadow}Cleft of Shadow{/link} zu führen.]=],
		},
		{
			title = "Taten",
			text = [=[• Er untersucht die sengenden Halsbänder der Burning Blade.
• Er befiehlt die Zerstörung der Dämonensaat, eines Gegenstands dämonischer Macht, auf dem {link:dreadmist-peak}Glutnebelgipfel{/link} im {link:the-barrens}Brachland{/link}.
• Er schickt Helden in den {link:ragefire-chasm}Ragefireabgrund{/link}, um die Teufelswache {link:taragaman-the-hungerer}Taragaman{/link} zu erschlagen.
• Er handelt mit dem {link:witch-doctor-uzer-i}Hexendoktor Uzer'i{/link} aus {link:feralas}Feralas{/link} mit Kräutern.]=],
		},
	},
	chapters = {
		{
			title = "Das sengende Halsband",
			hint = [=[Bringt ein sengendes Halsband von Margoz ins Cleft of Shadow.]=],
			text = [=[Als {link:margoz}Margoz{/link} ihm ein sengendes Halsband schickte, untersuchte Neeru es genau. Er nannte den Kult, der es gefertigt hatte, die Burning Blade, und den Gegenstand der Macht, um den er sich schart: die Dämonensaat. Er wollte sie zerstört sehen.]=],
		},
		{
			title = "Die Dämonensaat",
			hint = "Zerstört die Dämonensaat auf dem Glutnebelgipfel.",
			text = [=[Neerus Gehilfe Ak'Zeloth bereitete Steine vor, um die Bindung der Saat an die Legion zu brechen. Als die Saat zerstört wurde, gingen Wellen der Macht durch den Äther. Ak'Zeloth spürte sie, und er warnte, dass auch andere sie gespürt hätten.]=],
		},
		{
			title = "Wahre Treue",
			hint = "Erfahrt, was der Kriegshäuptling über Neeru weiß.",
			text = [=[Neeru ist der geheime Anführer der Burning Blade und ein Diener des {link:shadow-council}Schattenrats{/link}. Er hält {link:thrall}Thrall{/link} für einen Narren, der ihm vertraut. Er irrt sich: Der Kriegshäuptling weiß es und lässt ihn leben, weil er nützlich ist. Neeru schickt Thralls treue Gefolgsleute in den {link:ragefire-chasm}Ragefireabgrund{/link}, um dort zu sterben, und er prüft die Searing Blade, um zu sehen, welche ihrer Mitglieder würdig sind. Als ein junger Leutnant der Blade mit dem richtigen Abzeichen zu ihm kam, hieß Neeru einen Spion willkommen.]=],
		},
		{
			title = "Der Hungrige",
			hint = "Erschlagt die Teufelswache, die die Searing Blade anführt.",
			text = [=[Neeru nannte die Teufelswache {link:taragaman-the-hungerer}Taragaman{/link} den Hungrigen als Herrn der Searing Blade und verlangte sein Herz, um den Kriegshäuptling zufriedenzustellen. Die Searing Blade war für ihn entbehrlich. Nur zwei ihrer Anführer zählten, und die Teufelswache gehörte nicht dazu.]=],
		},
	},
	mentions = {
		{ text = "Neeru Fireblade" },
		{ text = "Brennende Schatten" },
		{ text = "Ak'Zeloth" },
		{ text = "Die Dämonensaat" },
		{ text = "Verborgene Feinde" },
		{ text = "Das Untier erschlagen" },
		{ text = "Eine seltsame Bitte" },
	},
	bonds = {
		{ id = "thrall", name = "Thrall", note = "der Kriegshäuptling, der ihn beobachtet" },
		{ id = "margoz", name = "Margoz", note = "schickte ihm ein Halsband" },
		{ id = "gazz-uz", name = "Gazz'uz", note = "ein Diener der Blade" },
		{ id = "taragaman-the-hungerer", name = "Taragaman der Hungrige", note = "die Teufelswache, die er preisgab" },
	},
})

Translate("deDE", "zor-lonetree", {
	title = "Zor Lonetree",
	subtitle = "Ältester Scharfseher",
	found = "Grommash Hold",
	hint = "Sprecht mit dem Scharfseher, der in Grommash Hold dient.",
	allegiance = "Horde",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Zor Lonetree ist ein ältester Scharfseher der {link:horde}Horde{/link}, ein Schamane von vielen Jahren, der in {link:grommash-hold}Grommash Hold{/link} dient. Er horcht auf die Schreie des Landes und schickt Hilfe dorthin, wo die Geister erzürnt sind. Er ist auch in der Politik der {link:alliance}Allianz{/link} wohlbewandert, und die Horde bringt ihm die Geheimnisse, die sie Menschenhänden entreißt.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Zor ist eine der weisen Stimmen um den Kriegshäuptling. Er hört sowohl die Geister als auch das Flüstern des Feindes.]=],
		},
		{
			title = "Taten",
			text = [=[• Er schickt der Schamanin {link:seereth-stonebreak}Seereth Stonebreak{/link} Hilfe, die gegen die Goblins kämpft, welche die Wälder des {link:stonetalon-mountains}Steinkrallengebirges{/link} niederbrennen.
• Er untersucht einen Anhänger eines Adligen, der menschlichen Soldaten abgenommen wurde.]=],
		},
	},
	mentions = {
		{ text = "Die Geister des Steinkrallengebirges" },
		{ text = "Meldet Euch bei Zor" },
		{ text = "Dienst an der {link:horde}Horde{/link}" },
	},
	bonds = {
		{ id = "thrall", name = "Thrall", note = "sein Kriegshäuptling" },
	},
})

Translate("deDE", "overlord-runthak", {
	title = "Oberherr Runthak",
	subtitle = "Oberherr des Valley of Strength",
	found = "Das Valley of Strength",
	hint = [=[Sprecht mit dem Oberherrn, der im Valley of Strength Wache hält.]=],
	allegiance = "Horde",
	aliases = { "Runthak" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Oberherr Runthak führt die Befehle des Kriegshäuptlings ohne Widerrede aus. Er sagt es selbst, und er ist stolz darauf. Er hält Ordnung im {link:valley-of-strength}Valley of Strength{/link} und wacht über seine Menschenmengen. Wenn ein Held der {link:horde}Horde{/link} mit dem Kopf eines großen Feindes zurückkehrt, ist es Runthak, der die Stadt ruft, um ihn zu sehen.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Runthak ist die Stimme der Triumphe der {link:horde}Horde{/link}. Durch ihn erfährt das Volk von {link:orgrimmar}Orgrimmar{/link} die Namen jener, die für es kämpfen.]=],
		},
		{
			title = "Taten",
			text = [=[• Er richtet die Trophäen der Siege der {link:horde}Horde{/link} über dem {link:valley-of-strength}Valley of Strength{/link} auf.
• Er belohnt die Helden, die der Kriegshäuptling zu ihm schickt.]=],
		},
	},
	mentions = {
		{ text = "Für alle sichtbar" },
		{ text = "Die Reise hat gerade erst begonnen" },
	},
	bonds = {
		{ id = "thrall", name = "Thrall", note = "sein Kriegshäuptling" },
	},
})

Translate("deDE", "gamon", {
	title = "Gamon",
	subtitle = "Stammgast der Taverne",
	found = "Die Taverne im Valley of Strength",
	hint = [=[Sucht den Tauren, der in der Taverne im Valley of Strength trinkt.]=],
	allegiance = "Keine",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Gamon ist ein großer Taure, den man meist in der Taverne im {link:valley-of-strength}Valley of Strength{/link} findet, und selten nüchtern. Er arbeitet als Gehilfe von Tazan, einem Troll, der mit den Piraten nahe {link:ratchet}Ratchet{/link} handelt. Gamon verwahrt für seinen Herrn Dinge, die andere gern hätten. Er bemerkt nicht immer, wenn sie verschwinden. Die Schurken des Cleft wissen das gut.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Gamon ist eine kleine Gestalt in einer großen Stadt. Doch selbst ein Trunkenbold kann einen Schlüssel besitzen, den die Shattered Hand so sehr will, dass sie ihn stiehlt.]=],
		},
		{ title = "Taten", text = "• Er verwahrt den Schlüssel zu Tazans Tasche." },
	},
	mentions = {
		{ text = "Die Shattered Hand" },
	},
	bonds = {
		{ id = "therzok", name = "Therzok", note = "will seinen Schlüssel" },
	},
})

Translate("deDE", "kor-ghan", {
	title = "Kor'ghan",
	subtitle = "Giftmischer des Cleft",
	found = "Das Cleft of Shadow",
	hint = "Sucht den Trollgiftmischer im Cleft of Shadow.",
	allegiance = "Darkspear",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Kor'ghan ist ein Troll der {link:darkspear-trolls}Darkspear{/link}, der im {link:cleft-of-shadow}Cleft of Shadow{/link} arbeitet. Er kennt die Gifte der Skorpide Durotars und weiß, wie man das Gift eines Skorpids in sein Gegenmittel verwandelt. Er ist auch ein strenger Meister der Rituale, und wer von ihm lernt, muss sich immer wieder beweisen. Seine Schüler klagen, aber sie bleiben am Leben.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Kor'ghan ist derjenige, den die Jungen Durotars aufsuchen, wenn das Gift eines Skorpids in ihrem Blut ist.]=],
		},
		{
			title = "Taten",
			text = [=[• Er braut ein Gegengift gegen das Gift der Giftschwänze aus den Giftbeuteln der Skorpide selbst.
• Er rettete den jungen Krieger Rhinag vor dem Stich eines Giftschwanzes.]=],
		},
	},
	mentions = {
		{ text = "Ein Heilmittel wird gebraucht" },
		{ text = "Das Gegengift finden" },
	},
})
